import{M as e,U as t,W as n,it as r}from"./chunks/framework.B6iJhav1.js";var i=JSON.parse(`{"title":"黑名单","description":"","frontmatter":{},"headers":[],"relativePath":"technical/blacklists.md","filePath":"technical/blacklists.md","lastUpdated":1786873544000}`),a={name:`technical/blacklists.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="blacklists" tabindex="-1">黑名单 <a class="header-anchor" href="#blacklists" aria-label="Permalink to “黑名单”">​</a></h1><p><strong>黑名单 (Blacklists)</strong> 是一种针对特定用户的惩罚措施，用于剥夺用户对于部分或全部命令的调用权。</p><p>在用户调用命令时，子悦机器会先检查用户是否在黑名单内。在黑名单内则拒绝调用，并返回被封禁的通知。</p><p>子悦机器中的黑名单记录不包括封禁时长，因此在技术上，<strong>黑名单是永久的</strong>。但同时，黑名单中的记录可以被删除，意味着针对用户的封禁可以被撤销。</p><p><strong>黑名单记录只能被手动添加到数据库表中。</strong></p><p>黑名单被储存在子悦机器数据库的“blacklists”表中，包含以下字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>解释</th></tr></thead><tbody><tr><td>userid</td><td>bigint(20)</td><td>用户 ID（主键）</td></tr><tr><td>command</td><td>varchar(50)</td><td>命令 ID（主键）</td></tr><tr><td>time</td><td>datetime</td><td>封禁的开始时间</td></tr><tr><td>reason</td><td>text</td><td>封禁原因</td></tr></tbody></table><p>黑名单分为 <strong>命令封禁</strong> 和 <strong>全局封禁</strong>。命令封禁针对特定命令，而全局封禁则是所有命令。</p><p>如果要添加全局封禁记录，只需要把 <code>command</code> 字段设置为 <code>all</code>。</p><p>子悦机器找到全局封禁记录时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>您已被禁止使用子悦机器！</span></span>
<span class="line"><span>时间：{日期时间}</span></span>
<span class="line"><span>原因：{原因}</span></span>
<span class="line"><span>用户协议：https://docs.ziyuebot.cn/tos.html</span></span></code></pre></div><p>找到命令封禁记录时：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>您已被禁止使用该命令！</span></span>
<span class="line"><span>时间：{日期时间}</span></span>
<span class="line"><span>原因：{原因}</span></span>
<span class="line"><span>用户协议：https://docs.ziyuebot.cn/tos.html</span></span></code></pre></div>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};